1	package com.example.starter.runway;
2	
3	import com.example.starter.runway.dto.*;
4	import org.springframework.dao.DuplicateKeyException;
5	import org.springframework.stereotype.Service;
6	import org.springframework.transaction.annotation.Transactional;
7	
8	import java.nio.charset.StandardCharsets;
9	import java.security.MessageDigest;
10	import java.security.NoSuchAlgorithmException;
11	import java.time.Clock;
12	import java.time.Instant;
13	import java.time.temporal.ChronoUnit;
14	import java.util.ArrayList;
15	import java.util.Comparator;
16	import java.util.List;
17	import java.util.Locale;
18	
19	/**
20	 * 跑道临时关闭巡检与开放决策服务：状态流转、幂等、并发与事务边界在此实现。
21	 */
22	@Service
23	public class RunwayService {
24	
25	    private static final String SCOPE_REPORT = "report";
26	    private static final String SCOPE_ASSESSMENT = "assessment";
27	    private static final String SCOPE_REOPEN = "reopen";
28	
29	    private final RunwayEventRepository eventRepository;
30	    private final InspectionRepository inspectionRepository;
31	    private final AssessmentRepository assessmentRepository;
32	    private final NotamRepository notamRepository;
33	    private final WeatherRepository weatherRepository;
34	    private final RunwayProperties properties;
35	    private final IdempotencyExecutor idempotencyExecutor;
36	    private final Clock clock;
37	
38	    public RunwayService(RunwayEventRepository eventRepository,
39	                         InspectionRepository inspectionRepository,
40	                         AssessmentRepository assessmentRepository,
41	                         NotamRepository notamRepository,
42	                         WeatherRepository weatherRepository,
43	                         RunwayProperties properties,
44	                         IdempotencyExecutor idempotencyExecutor,
45	                         Clock clock) {
46	        this.eventRepository = eventRepository;
47	        this.inspectionRepository = inspectionRepository;
48	        this.assessmentRepository = assessmentRepository;
49	        this.notamRepository = notamRepository;
50	        this.weatherRepository = weatherRepository;
51	        this.properties = properties;
52	        this.idempotencyExecutor = idempotencyExecutor;
53	        this.clock = clock;
54	    }
55	
56	    /**
57	     * 接报：即触发临时关闭并同步发布关闭通告；requestId 幂等；同一跑道唯一进行中事件。
58	     */
59	    public ReportResponse report(ReportRequest request) {
60	        String fingerprint = fingerprint(SCOPE_REPORT, request.requestId(), request.runwayId(),
61	                request.eventType().name(), request.reportedAt().toString());
62	        try {
63	            return idempotencyExecutor.execute(SCOPE_REPORT, request.requestId(), fingerprint,
64	                    () -> doReport(request), ReportResponse.class);
65	        } catch (DuplicateKeyException e) {
66	            ReportResponse replayed = idempotencyExecutor.tryReplay(SCOPE_REPORT, request.requestId(),
67	                    fingerprint, ReportResponse.class);
68	            if (replayed != null) {
69	                return replayed;
70	            }
71	            if (isActiveEventConflict(e)) {
72	                throw ApiException.conflict("RUNWAY_ACTIVE_EVENT_EXISTS", "同一跑道已存在进行中的关闭事件");
73	            }
74	            throw e;
75	        }
76	    }
77	
78	    private ReportResponse doReport(ReportRequest request) {
79	        Instant now = clock.instant();
80	        Instant closedAt = request.reportedAt();
81	        Instant deadline = closedAt.plus(properties.inspectionStartLimitMinutes(), ChronoUnit.MINUTES);
82	        RunwayEvent event = new RunwayEvent(0L, request.runwayId(), request.eventType(), EventStatus.CLOSED,
83	                request.reportedAt(), closedAt, deadline, false, null, request.requestId(), now, now);
84	        event = eventRepository.insert(event, 1);
85	        String notamNo = "NTM-C-" + event.id();
86	        notamRepository.insert(new NotamRecord(0L, event.id(), event.runwayId(), NotamAction.CLOSE,
87	                notamNo, closedAt));
88	        return new ReportResponse(event.id(), event.runwayId(), event.status().name(), closedAt, deadline, notamNo);
89	    }
