91	    /**
92	     * 巡检开始：恰满15分钟未开始判定迟延并升级；低能见度须双人，单人记录不生效；
93	     * 归档后迟到巡检仅登记迟到事件。
94	     */
95	    @Transactional
96	    public InspectionResponse startInspection(long eventId, InspectionRequest request) {
97	        RunwayEvent event = mustFind(eventId);
98	        Instant now = clock.instant();
99	        if (event.status() == EventStatus.ARCHIVED) {
100	            InspectionRecord lateRecord = inspectionRepository.insert(new InspectionRecord(0L, eventId,
101	                    request.startedAt(), request.inspectorCount(), true, true, now));
102	            return new InspectionResponse(lateRecord.id(), eventId, true, event.escalated(), true,
103	                    event.status().name());
104	        }
105	        if (event.status() == EventStatus.REOPENED) {
106	            throw ApiException.conflict("EVENT_NOT_ACTIVE", "事件已恢复开放，不再受理巡检");
107	        }
108	        boolean late = !request.startedAt().isBefore(event.inspectionDeadline());
109	        boolean lowVisibility = weatherRepository.findLatestAtOrBefore(event.runwayId(), request.startedAt())
110	                .map(reading -> reading.rvrMeters() < properties.lowVisibilityRvrThreshold())
111	                .orElse(false);
112	        if (lowVisibility && request.inspectorCount() < 2) {
113	            throw ApiException.unprocessable("LOW_VISIBILITY_REQUIRES_DUAL",
114	                    "低能见度期间巡检须双人执行，单人记录不生效");
115	        }
116	        InspectionRecord record = inspectionRepository.insert(new InspectionRecord(0L, eventId,
117	                request.startedAt(), request.inspectorCount(), late, false, now));
118	        boolean escalated = event.escalated() || late;
119	        EventStatus newStatus = event.status() == EventStatus.CLOSED ? EventStatus.INSPECTING : event.status();
120	        eventRepository.updateStatus(eventId, newStatus, escalated, event.assessmentType(), false, now);
121	        return new InspectionResponse(record.id(), eventId, late, escalated, false, newStatus.name());
122	    }
