127	    public AssessmentResponse assess(long eventId, AssessmentRequest request) {
128	        String fingerprint = fingerprint(SCOPE_ASSESSMENT, request.requestId(), String.valueOf(eventId),
129	                request.frictionCoefficient().toPlainString(), request.assessmentType().name(),
130	                request.assessedAt().toString());
