234	    @Transactional(readOnly = true)
235	    public EventDetailResponse getDetail(long eventId) {
236	        RunwayEvent event = mustFind(eventId);
237	        List<TimelineEntry> timeline = new ArrayList<>();
238	        timeline.add(new TimelineEntry("REPORTED", event.reportedAt(),
239	                "接报" + event.eventType() + "，触发临时关闭"));
240	        for (NotamRecord notam : notamRepository.findByEventId(eventId)) {
241	            timeline.add(new TimelineEntry(notam.action() == NotamAction.CLOSE ? "CLOSED_NOTAM" : "REOPEN_NOTAM",
242	                    notam.publishedAt(), "航行通告 " + notam.noticeNo()));
243	        }
244	        boolean escalatedMarked = false;
245	        for (InspectionRecord inspection : inspectionRepository.findByEventId(eventId)) {
246	            if (inspection.recordedAfterArchive()) {
247	                timeline.add(new TimelineEntry("LATE_INSPECTION_RECORDED", inspection.startedAt(),
248	                        "归档后迟到巡检记录，仅登记"));
249	                continue;
250	            }
251	            timeline.add(new TimelineEntry("INSPECTION_STARTED", inspection.startedAt(),
252	                    "巡检开始，人数" + inspection.inspectorCount() + (inspection.late() ? "，迟延" : "")));
253	            if (inspection.late() && !escalatedMarked) {
254	                timeline.add(new TimelineEntry("ESCALATED", inspection.startedAt(), "巡检迟延，事件升级"));
255	                escalatedMarked = true;
256	            }
257	        }
258	        for (AssessmentRecord assessment : assessmentRepository.findByEventIdOrderByAssessedAt(eventId)) {
259	            timeline.add(new TimelineEntry("ASSESSED", assessment.assessedAt(),
260	                    "摩擦系数" + assessment.frictionCoefficient().toPlainString()
261	                            + (assessment.passed() ? "，合格" : "，不合格持续关闭")
262	                            + (assessment.retest() ? "（复测）" : "")));
263	        }
264	        if (event.status() == EventStatus.REOPENED) {
265	            notamRepository.findByEventId(eventId).stream()
266	                    .filter(n -> n.action() == NotamAction.REOPEN)
267	                    .findFirst()
268	                    .ifPresent(n -> timeline.add(new TimelineEntry("REOPENED", n.publishedAt(), "恢复开放")));
269	        }
270	        if (event.status() == EventStatus.ARCHIVED) {
271	            timeline.add(new TimelineEntry("ARCHIVED", event.updatedAt(), "事件归档（终态）"));
272	        }
273	        timeline.sort(Comparator.comparing(TimelineEntry::at));
274	        return new EventDetailResponse(event.id(), event.runwayId(), event.eventType().name(),
275	                event.status().name(), event.reportedAt(), event.closedAt(), event.inspectionDeadline(),
276	                event.escalated(), timeline);
277	    }
