327	    private void requireActive(RunwayEvent event, String operation) {
328	        if (event.status() == EventStatus.ARCHIVED) {
329	            throw ApiException.conflict("EVENT_ARCHIVED", "事件已归档，不再受理" + operation);
330	        }
331	        if (event.status() == EventStatus.REOPENED) {
332	            throw ApiException.conflict("EVENT_NOT_ACTIVE", "事件已恢复开放，不再受理" + operation);
333	        }
