336	    private boolean isActiveEventConflict(DuplicateKeyException e) {
337	        String message = String.valueOf(e.getMessage()).toLowerCase(Locale.ROOT);
338	        return message.contains("uk_runway_event_active");
339	    }
340	
341	    private String fingerprint(String... parts) {
342	        try {
343	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
344	            byte[] hash = digest.digest(String.join("|", parts).getBytes(StandardCharsets.UTF_8));
345	            StringBuilder hex = new StringBuilder(hash.length * 2);
346	            for (byte b : hash) {
347	                hex.append(Character.forDigit((b >> 4) & 0xF, 16)).append(Character.forDigit(b & 0xF, 16));
348	            }
349	            return hex.toString();
350	        } catch (NoSuchAlgorithmException e) {
351	            throw new IllegalStateException("SHA-256 不可用", e);
352	        }
353	    }
