32	    /**
33	     * 幂等记录行。
34	     *
35	     * @param scope        作用域
36	     * @param requestId    请求标识
37	     * @param fingerprint  请求指纹
38	     * @param responseBody 首次响应报文（JSON）
39	     */
40	    public record IdemRow(String scope, String requestId, String fingerprint, String responseBody) {
41	    }
42	
43	    public Optional<IdemRow> find(String scope, String requestId) {
44	        List<IdemRow> rows = jdbc.query(
45	                "SELECT * FROM idempotency_record WHERE scope = ? AND request_id = ?",
46	                MAPPER, scope, requestId);
47	        return rows.stream().findFirst();
48	    }
49	
50	    public void insert(String scope, String requestId, String fingerprint, String responseBody) {
51	        jdbc.update("INSERT INTO idempotency_record (scope, request_id, fingerprint, response_body, created_at)"
52	                        + " VALUES (?,?,?,?,?)",
53	                scope, requestId, fingerprint, responseBody, Timestamp.from(clock.instant()));
54	    }
