60	                new InspectionRequest(T0.plus(Duration.ofMinutes(5)), 2));
61	        assertFalse(inspection.late());
62	        assertFalse(inspection.escalated());
63	        assertEquals(EventStatus.INSPECTING.name(), inspection.eventStatus());
64	
65	        AssessmentResponse assessed = service.assess(reported.eventId(),
66	                new AssessmentRequest("assess-1", new BigDecimal("0.50"), AssessmentType.CLEAR_TO_REOPEN,
67	                        T0.plus(Duration.ofMinutes(8))));
68	        assertTrue(assessed.passed());
