113	    @Test
114	    void frictionExactlyThresholdPassesButBelowKeepsClosed() {
115	        ReportResponse reported = report("req-friction", "RW04");
116	        service.startInspection(reported.eventId(), new InspectionRequest(T0.plus(Duration.ofMinutes(3)), 2));
117	
118	        AssessmentResponse exactly = service.assess(reported.eventId(),
