36	    public InspectionRecord insert(InspectionRecord record) {
37	        KeyHolder keyHolder = new GeneratedKeyHolder();
38	        jdbc.update(connection -> {
39	            PreparedStatement ps = connection.prepareStatement(
40	                    "INSERT INTO inspection_record (event_id, started_at, inspector_count, late,"
41	                            + " recorded_after_archive, created_at) VALUES (?,?,?,?,?,?)",
42	                    Statement.RETURN_GENERATED_KEYS);
43	            ps.setLong(1, record.eventId());
44	            ps.setTimestamp(2, Timestamp.from(record.startedAt()));
45	            ps.setInt(3, record.inspectorCount());
