    runway_id VARCHAR(32) NOT NULL,
    rvr_meters INT NOT NULL,
    recorded_at TIMESTAMP NOT NULL
);

COMMENT ON TABLE weather_reading IS '气象读数（合成）：按跑道记录RVR，用于低能见度双人巡检判定';
